use iced::widget::svg::{Handle, Svg};
use iced::Color;

pub fn render_svg_icon<'a>(
    svg_bytes: &'static [u8],
    size: u16,
    color: Color,
) -> Svg<'a, iced::Theme> {
    iced::widget::svg(Handle::from_memory(svg_bytes))
        .width(size)
        .height(size)
        .style(move |_theme, _status| iced::widget::svg::Style { color: Some(color) })
}

